{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer korrekt, at udtalelsen er vejledende, at Udbetaling Danmark ikke er bundet, og at den bygger på sagens dokumentation uden undersøgelse. Det udelader dog det andet centrale punkt: om funktionsevnen er så nedsat, at den uddannelsessøgende ikke kan have et studiejob. Det beskriver kun generelt 'evne til at arbejde'. Desuden tilføjer svaret, at Udbetaling Danmark 'kan fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning', og det er ikke understøttet af kilden. Samlet er svaret ikke fuldt korrekt."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element (hvor meget funktionsnedsættelsen påvirker evnen til at arbejde) er dækket med ækvivalent ordlyd. Det andet kritiske element (om funktionsevnen er så nedsat, at et studiejob ikke kan varetages) mangler helt. Svaret nævner aldrig studiejob."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet. Indholdet er relevant. Manglen på studiejobelementet er en fuldstændighedsfejl, ikke en relevansfejl."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, vejledning nr. 10157 (afsnit om udtalelse fra AES). Det citerer også direkte fra den."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning VEJ nr. 10157 findes i det frosne kildemateriale, er autoritativ og er anvendelig til spørgsmålet. Afsnit 5.1.3.3 er netop det relevante afsnit."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De fleste påstande understøttes af afsnit 5.1.3.3. Men påstanden om, at Udbetaling Danmark 'kan dog fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning', er knyttet til kilde 2, som kun siger, at udtalelsen indgår i vurderingen og ikke er bindende. Den siger ikke noget om at fravige på grund af anden dokumentation. Påstanden 'skal inddrage udtalelsen' er også gengivet stærkere end kilden. Desuden henviser svaret til kilde 3 for 'meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde', som ikke fremgår af den udleverede vejledningspassage, men af SU-loven § 7, stk. 3 og bekendtgørelsen § 36."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at Udbetaling Danmark 'kan fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning'. Det er en retsvirkning, som ikke fremgår af kilderne. Det tilføjer også, at udtalelsen skal belyse evnen til at 'påtage sig erhvervsarbejde'. Det er lovens tærskel for tillægget, ikke vejledningens beskrivelse af AES' vurdering."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den krævede kvalifikation er bevaret: udtalelsen er vejledende, og Udbetaling Danmark er ikke bundet af den. Svaret nævner også, at den uddannelsessøgende ikke kan klage, og at udtalelsen bygger på sagens dokumentation uden undersøgelse."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinene er sammenhængende. Udtalelsen er vejledende, og derfor er Udbetaling Danmark ikke bundet, men inddrager den. Konklusionen følger af det, svaret selv anfører. Der er ingen interne modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret skriver, at Udbetaling Danmark 'skal inddrage udtalelsen'. Kilden siger, at udtalelsen 'indgår i' vurderingen. Det skaber en pligt, kilden ikke udtrykker. Svaret sige også, at Udbetaling Danmark 'kan dog fravige' udtalelsen, og det gengiver ikke kildens formulering. Konklusionen bruger samtidig 'mest nærliggende på det foreliggende grundlag', hvilket er upræcist for en klar regel."
    }
  },
  "xhaile_coverage": {
    "A68": {
      "label": "partial",
      "reason": "Svaret dækker, at Udbetaling Danmark kan indhente en vejledende udtalelse om evnen til at arbejde, og at den bygger på sagens dokumentation uden undersøgelse. Svaret dækker hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, i ækvivalent form. Det udelader vurderingen af, om funktionsevnen er så nedsat, at et studiejob ikke kan varetages, og at Udbetaling Danmark betaler udgifterne."
    }
  },
  "overall_notes": "Svaret er korrekt på det vejledende og ikke-bindende element og på dokumentgrundlaget, men mangler studiejobvurderingen, som er det andet kritiske element. Det tilføjer en uunderbygget regel om, at Udbetaling Danmark kan fravige udtalelsen, og er upræcist i modaliteten med 'skal inddrage'. Kilderne er identificerbare og gyldige, men støtter ikke alle påstande."
}

